import * as THREE from '../vendor/three.module.js'

const mat = (color, opts = {}) => new THREE.MeshLambertMaterial({ color, ...opts })
const box = (w, h, d, material) => {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material)
  m.castShadow = true
  m.receiveShadow = true
  return m
}

export const HATS = {
  none: { name: 'Bare Head', desc: 'Let the breeze through your hair.' },
  explorer: { name: 'Trail Hat', desc: 'A trusty brim for sky explorers.' },
  crown: { name: 'Sun Crown', desc: 'For the ruler of Sunnyhollow.' },
  wizard: { name: 'Cloud Wizard', desc: 'A pointy hat full of weather.' }
}

export function createCharacter(opts = {}) {
  const colors = {
    skin: opts.skin || '#f0c49b',
    hair: opts.hair || '#5b3a25',
    shirt: opts.shirt || '#2fb6c9',
    shirt2: opts.shirt2 || '#1f8fa3',
    pants: opts.pants || '#5d4b8c',
    shoes: opts.shoes || '#3a2e4e',
    backpack: opts.backpack || '#c1803f',
    hat: opts.hatColor || '#f2c34a'
  }
  const mats = {
    skin: mat(colors.skin), hair: mat(colors.hair), shirt: mat(colors.shirt),
    shirt2: mat(colors.shirt2), pants: mat(colors.pants), shoes: mat(colors.shoes),
    backpack: mat(colors.backpack), dark: mat('#2a2233'), white: mat('#fff8ee'),
    gold: mat('#f2c34a'), purple: mat('#7b4bc4'), straw: mat('#e6c27a'), blush: mat('#ef9d8f')
  }

  const root = new THREE.Group()
  const bob = new THREE.Group()
  root.add(bob)

  // legs
  const legL = new THREE.Group(); legL.position.set(-0.16, 0.62, 0)
  const legR = new THREE.Group(); legR.position.set(0.16, 0.62, 0)
  const legMeshL = box(0.25, 0.62, 0.28, mats.pants); legMeshL.position.y = -0.31
  const legMeshR = box(0.25, 0.62, 0.28, mats.pants); legMeshR.position.y = -0.31
  const shoeL = box(0.27, 0.14, 0.36, mats.shoes); shoeL.position.set(0, -0.55, 0.05)
  const shoeR = box(0.27, 0.14, 0.36, mats.shoes); shoeR.position.set(0, -0.55, 0.05)
  legL.add(legMeshL, shoeL); legR.add(legMeshR, shoeR)
  bob.add(legL, legR)

  // torso
  const torso = box(0.62, 0.64, 0.38, mats.shirt)
  torso.position.y = 0.94
  bob.add(torso)
  const belt = box(0.64, 0.1, 0.4, mats.shirt2)
  belt.position.y = 0.66
  bob.add(belt)
  const buckle = box(0.12, 0.1, 0.03, mats.gold)
  buckle.position.set(0, 0.66, 0.21)
  bob.add(buckle)

  // little backpack
  const pack = box(0.44, 0.42, 0.2, mats.backpack)
  pack.position.set(0, 0.98, -0.27)
  bob.add(pack)
  const packFlap = box(0.46, 0.12, 0.22, mat('#a96a33'))
  packFlap.position.set(0, 1.14, -0.27)
  bob.add(packFlap)
  for (const x of [-0.22, 0.22]) {
    const strap = box(0.07, 0.5, 0.05, mat('#8a5a2f'))
    strap.position.set(x, 0.98, -0.16)
    bob.add(strap)
  }

  // arms
  const armL = new THREE.Group(); armL.position.set(-0.41, 1.18, 0)
  const armR = new THREE.Group(); armR.position.set(0.41, 1.18, 0)
  const armMeshL = box(0.22, 0.56, 0.24, mats.shirt); armMeshL.position.y = -0.28
  const armMeshR = box(0.22, 0.56, 0.24, mats.shirt); armMeshR.position.y = -0.28
  const handL = box(0.2, 0.16, 0.22, mats.skin); handL.position.y = -0.62
  const handR = box(0.2, 0.16, 0.22, mats.skin); handR.position.y = -0.62
  armL.add(armMeshL, handL); armR.add(armMeshR, handR)
  bob.add(armL, armR)

  // head
  const head = new THREE.Group()
  head.position.y = 1.26
  const skull = box(0.66, 0.62, 0.62, mats.skin)
  skull.position.y = 0.33
  head.add(skull)
  // hair cap
  const hair = box(0.7, 0.2, 0.66, mats.hair)
  hair.position.y = 0.63
  head.add(hair)
  const fringe = box(0.7, 0.13, 0.12, mats.hair)
  fringe.position.set(0, 0.55, 0.29)
  head.add(fringe)
  const sideHairL = box(0.1, 0.28, 0.5, mats.hair)
  sideHairL.position.set(-0.34, 0.42, -0.02)
  const sideHairR = sideHairL.clone(); sideHairR.position.x = 0.34
  head.add(sideHairL, sideHairR)
  // face
  for (const x of [-0.16, 0.16]) {
    const eye = box(0.08, 0.12, 0.03, mats.dark)
    eye.position.set(x, 0.34, 0.32)
    head.add(eye)
    const glint = box(0.03, 0.04, 0.02, mats.white)
    glint.position.set(x + 0.02, 0.37, 0.34)
    head.add(glint)
    const cheek = box(0.09, 0.05, 0.02, mats.blush)
    cheek.position.set(x * 1.65, 0.22, 0.32)
    head.add(cheek)
  }
  const mouth = box(0.16, 0.035, 0.02, mat('#9c5a50'))
  mouth.position.set(0, 0.16, 0.325)
  head.add(mouth)
  // eyebrows
  for (const x of [-0.16, 0.16]) {
    const brow = box(0.13, 0.035, 0.02, mats.hair)
    brow.position.set(x, 0.45, 0.325)
    head.add(brow)
  }
  bob.add(head)

  // hats
  const hats = {}
  {
    const g = new THREE.Group()
    const band = new THREE.Mesh(new THREE.CylinderGeometry(0.4, 0.42, 0.14, 10), mats.gold)
    band.position.y = 0.7
    g.add(band)
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * Math.PI * 2
      const spike = new THREE.Mesh(new THREE.ConeGeometry(0.075, 0.2, 4), mats.gold)
      spike.position.set(Math.cos(a) * 0.34, 0.83, Math.sin(a) * 0.34)
      g.add(spike)
    }
    const jewel = new THREE.Mesh(new THREE.OctahedronGeometry(0.07), mat('#ff5f8f', { emissive: '#7a1636', emissiveIntensity: .3 }))
    jewel.position.set(0, 0.73, 0.4)
    g.add(jewel)
    hats.crown = g
  }
  {
    const g = new THREE.Group()
    const brim = new THREE.Mesh(new THREE.CylinderGeometry(0.52, 0.55, 0.07, 12), mats.purple)
    brim.position.y = 0.7
    const cone = new THREE.Mesh(new THREE.ConeGeometry(0.38, 0.62, 12), mats.purple)
    cone.position.y = 1.03
    const band = new THREE.Mesh(new THREE.CylinderGeometry(0.4, 0.4, 0.1, 12), mats.gold)
    band.position.y = 0.76
    g.add(brim, cone, band)
    for (let i = 0; i < 5; i++) {
      const a = i * 1.7
      const star = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.07, 0.02), mat('#ffe28a', { emissive: '#7a5a10', emissiveIntensity: .4 }))
      star.position.set(Math.cos(a) * 0.26, 0.9 + (i % 3) * 0.1, Math.sin(a) * 0.26)
      g.add(star)
    }
    hats.wizard = g
  }
  {
    const g = new THREE.Group()
    const brim = new THREE.Mesh(new THREE.CylinderGeometry(0.52, 0.54, 0.06, 12), mats.straw)
    brim.position.y = 0.7
    const dome = new THREE.Mesh(new THREE.CylinderGeometry(0.34, 0.4, 0.28, 12), mats.straw)
    dome.position.y = 0.84
    const band = new THREE.Mesh(new THREE.CylinderGeometry(0.41, 0.41, 0.08, 12), mat('#6b8a4a'))
    band.position.y = 0.76
    g.add(brim, dome, band)
    hats.explorer = g
  }
  for (const key of Object.keys(hats)) {
    hats[key].visible = false
    hats[key].traverse(o => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true } })
    head.add(hats[key])
  }
  let currentHat = opts.hat || 'none'
  if (hats[currentHat]) hats[currentHat].visible = true

  // soft blob shadow so the character reads on every device
  const blob = new THREE.Mesh(
    new THREE.CircleGeometry(0.52, 24),
    new THREE.MeshBasicMaterial({ color: 0x1a1830, transparent: true, opacity: 0.22, depthWrite: false })
  )
  blob.rotation.x = -Math.PI / 2
  blob.position.y = 0.02
  root.add(blob)

  const state = { walk: 0, swing: 0, mine: 0, emote: 0, wave: 0, dance: 0 }

  function setHat(key) {
    for (const k of Object.keys(hats)) hats[k].visible = k === key
    currentHat = key
  }
  function setColors(c) {
    if (c.skin) mats.skin.color.set(c.skin)
    if (c.hair) mats.hair.color.set(c.hair)
    if (c.shirt) { mats.shirt.color.set(c.shirt); mats.shirt2.color.set(new THREE.Color(c.shirt).multiplyScalar(0.78)) }
    if (c.pants) mats.pants.color.set(c.pants)
    if (c.backpack) mats.backpack.color.set(c.backpack)
  }

  function update(dt, s = {}) {
    const speed = s.speed || 0
    const grounded = s.grounded !== false
    const time = s.time || 0
    state.walk += dt * (4 + speed * 1.25)
    state.swing += dt * (8 + speed)
    const moving = speed > 0.25 && grounded
    const targetLeg = moving ? Math.sin(state.walk * 1.8) * Math.min(0.75, 0.28 + speed * 0.08) : 0
    const targetArm = moving ? -Math.sin(state.walk * 1.8) * Math.min(0.7, 0.22 + speed * 0.075) : 0
    const air = !grounded
    const mine = s.mining ? 1 : 0
    const emote = s.emote || ''

    const damp = 1 - Math.pow(0.0001, dt)
    const lerpR = (obj, axis, target, speedMul = 1) => {
      obj.rotation[axis] += (target - obj.rotation[axis]) * Math.min(1, damp * speedMul)
    }

    if (air) {
      lerpR(legL, 'x', -0.45, 1.4); lerpR(legR, 'x', 0.35, 1.4)
      lerpR(armL, 'x', -1.3, 1.2); lerpR(armR, 'x', -1.1, 1.2)
      lerpR(armL, 'z', -0.35, 1.2); lerpR(armR, 'z', 0.35, 1.2)
    } else if (emote === 'dance') {
      const t = time * 7
      lerpR(armL, 'x', -1.9 + Math.sin(t) * 0.7, 2)
      lerpR(armR, 'x', -1.9 - Math.sin(t) * 0.7, 2)
      lerpR(armL, 'z', -0.5 + Math.cos(t) * 0.4, 2)
      lerpR(armR, 'z', 0.5 - Math.cos(t) * 0.4, 2)
      lerpR(legL, 'x', Math.sin(t) * 0.45, 2)
      lerpR(legR, 'x', -Math.sin(t) * 0.45, 2)
      bob.position.y = Math.abs(Math.sin(t)) * 0.09
      root.rotation.y += dt * 1.8
    } else if (emote === 'wave') {
      lerpR(armR, 'x', -2.5, 2.5)
      lerpR(armR, 'z', 0.5 + Math.sin(time * 9) * 0.3, 2.5)
      lerpR(armL, 'x', 0, 2)
      lerpR(legL, 'x', 0, 2); lerpR(legR, 'x', 0, 2)
    } else {
      lerpR(legL, 'x', targetLeg, 1.2)
      lerpR(legR, 'x', -targetLeg, 1.2)
      if (mine) {
        lerpR(armR, 'x', -1.7 + Math.sin(state.swing * 2.2) * 0.85, 2.4)
        lerpR(armR, 'z', 0.25, 2)
        lerpR(armL, 'x', targetArm * 0.5, 1.2)
        lerpR(armL, 'z', 0, 1.2)
      } else {
        lerpR(armL, 'x', targetArm, 1.2)
        lerpR(armR, 'x', -targetArm, 1.2)
        lerpR(armL, 'z', -0.06, 1.2)
        lerpR(armR, 'z', 0.06, 1.2)
      }
      if (emote !== 'dance') root.rotation.y += (0 - root.rotation.y) * Math.min(1, dt * 2)
      bob.position.y = moving ? Math.abs(Math.sin(state.walk * 1.8)) * 0.045 : Math.sin(time * 2.1) * 0.012
    }
    if (emote === 'dance') {
      bob.position.y = Math.abs(Math.sin(time * 7)) * 0.09
    }
    // head looks slightly toward camera pitch for life
    head.rotation.x += ((s.lookPitch || 0) * 0.35 - head.rotation.x) * Math.min(1, dt * 4)
    head.rotation.y = Math.sin(time * 0.5) * 0.04
  }

  return {
    root, bob, head, parts: { legL, legR, armL, armR, torso, skull, hats }, mats,
    setHat, setColors, update,
    get hat() { return currentHat }
  }
}

import * as THREE from '../vendor/three.module.js'
import { createCharacter } from './character.js'
import { BLOCKS, KEY_TO_ID, isWater, blockColor } from './blocks.js'
import { WORLD, HEIGHT } from './world.js'

const UP = new THREE.Vector3(0, 1, 0)
const clamp = (v, a, b) => Math.max(a, Math.min(b, v))
const damp = (a, b, lambda, dt) => a + (b - a) * (1 - Math.exp(-lambda * dt))
function dampAngle(a, b, lambda, dt) {
  let d = ((b - a + Math.PI) % (Math.PI * 2)) - Math.PI
  if (d < -Math.PI) d += Math.PI * 2
  return a + d * (1 - Math.exp(-lambda * dt))
}

export class Player {
  constructor(game, scene, world, camera) {
    this.game = game
    this.scene = scene
    this.world = world
    this.camera = camera
    this.pos = new THREE.Vector3(40.5, 12.05, 54.5)
    this.vel = new THREE.Vector3()
    this.radius = 0.31
    this.height = 1.78
    this.onGround = false
    this.coyote = 0
    this.jumpBuffer = 0
    this.speed = 0
    this.facing = Math.PI
    this.cameraYaw = 0
    this.cameraPitch = 0.26
    this.cameraDist = 6.9
    this.cameraTarget = new THREE.Vector3(this.pos.x, this.pos.y + 1.35, this.pos.z)
    this.cameraPos = new THREE.Vector3()
    this.lookSensitivity = 0.0023
    this.mineHold = false
    this.placeQueued = false
    this.mineProgress = 0
    this.target = null
    this.mineCooldown = 0
    this.placeCooldown = 0
    this.stepCooldown = 0
    this.walkTime = 0
    this.emote = ''
    this.emoteTimer = 0
    this.bounceCooldown = 0
    this.inWater = false
    this.fov = 62
    this.moveInput = { x: 0, y: 0 }
    this.jumpHeld = false
    this.sprint = false
    this.lastGroundY = this.pos.y
    this.spawn = new THREE.Vector3(40.5, 12.05, 54.5)

    this.character = createCharacter({ hat: 'explorer' })
    this.character.root.position.copy(this.pos)
    this.character.root.rotation.y = this.facing
    scene.add(this.character.root)

    this.buildHighlight()
    this.buildCrack()
    this.raycaster = new THREE.Raycaster()
  }

  buildHighlight() {
    const geo = new THREE.BoxGeometry(1.008, 1.008, 1.008)
    const edges = new THREE.EdgesGeometry(geo)
    this.highlight = new THREE.LineSegments(edges, new THREE.LineBasicMaterial({
      color: 0xffe28a, transparent: true, opacity: 0.95, depthTest: false
    }))
    this.highlight.renderOrder = 8
    this.highlight.visible = false
    this.scene.add(this.highlight)
    const faceMat = new THREE.MeshBasicMaterial({
      color: 0xffe28a, transparent: true, opacity: 0.09, depthWrite: false, side: THREE.DoubleSide
    })
    this.highlightFace = new THREE.Mesh(geo, faceMat)
    this.highlightFace.visible = false
    this.highlightFace.renderOrder = 7
    this.scene.add(this.highlightFace)
  }

  buildCrack() {
    const c = document.createElement('canvas')
    c.width = c.height = 32
    const ctx = c.getContext('2d')
    ctx.strokeStyle = 'rgba(24,18,12,.95)'
    ctx.lineWidth = 1.4
    let seed = 99
    const rand = () => { seed = (seed * 16807) % 2147483647; return seed / 2147483647 }
    for (let i = 0; i < 9; i++) {
      let x = 16, y = 16
      ctx.beginPath(); ctx.moveTo(x, y)
      for (let s = 0; s < 5; s++) { x += (rand() - .5) * 13; y += (rand() - .5) * 13; ctx.lineTo(x, y) }
      ctx.stroke()
    }
    const tex = new THREE.CanvasTexture(c)
    tex.magFilter = THREE.NearestFilter
    tex.minFilter = THREE.NearestFilter
    tex.generateMipmaps = false
    this.crackTex = tex
    this.crack = new THREE.Mesh(
      new THREE.BoxGeometry(1.012, 1.012, 1.012),
      new THREE.MeshBasicMaterial({ map: tex, transparent: true, opacity: 0, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -2 })
    )
    this.crack.visible = false
    this.crack.renderOrder = 9
    this.scene.add(this.crack)
  }

  resetToSpawn(notify = true) {
    this.pos.set(this.spawn.x, this.world.surfaceY(this.spawn.x, this.spawn.z) + 0.05, this.spawn.z)
    this.vel.set(0, 0, 0)
    this.cameraTarget.set(this.pos.x, this.pos.y + 1.35, this.pos.z)
    this.cameraPos.copy(this.cameraTarget)
    this.cameraYaw = 0
    this.cameraPitch = 0.26
    if (notify) this.game.notify('Whoops! The clouds caught you.', 'info')
  }

  look(dx, dy) {
    this.cameraYaw -= dx * this.lookSensitivity
    this.cameraPitch = clamp(this.cameraPitch + dy * this.lookSensitivity, -0.38, 1.12)
    this.cameraYaw = ((this.cameraYaw + Math.PI) % (Math.PI * 2) + Math.PI * 2) % (Math.PI * 2) - Math.PI
  }

  zoom(delta) {
    this.cameraDist = clamp(this.cameraDist + delta * 0.006, 3.8, 11)
  }

  setMove(x, y) { this.moveInput.x = clamp(x, -1, 1); this.moveInput.y = clamp(y, -1, 1) }
  jump() { this.jumpBuffer = 0.16; this.jumpHeld = true }
  releaseJump() { this.jumpHeld = false }
  startMine() { this.mineHold = true }
  stopMine() { this.mineHold = false; this.mineProgress = 0 }
  queuePlace() { this.placeQueued = true }
  playEmote(name) {
    this.emote = name
    this.emoteTimer = name === 'dance' ? 4.5 : 2.6
  }

  get selectedKey() { return this.game.selectedKey }

  getAABB(pos = this.pos) {
    return {
      minX: pos.x - this.radius, maxX: pos.x + this.radius,
      minY: pos.y, maxY: pos.y + this.height,
      minZ: pos.z - this.radius, maxZ: pos.z + this.radius
    }
  }
  collidesAt(pos) {
    const b = this.getAABB(pos)
    return this.world.collides(b.minX, b.minY, b.minZ, b.maxX, b.maxY, b.maxZ)
  }

  update(dt, time) {
    dt = Math.min(dt, 0.05)
    if (this.emoteTimer > 0) {
      this.emoteTimer -= dt
      if (this.emoteTimer <= 0) this.emote = ''
    }
    if (this.game.paused || !this.game.started) {
      this.updateVisual(dt, time)
      this.updateCamera(dt)
      return
    }

    this.mineCooldown = Math.max(0, this.mineCooldown - dt)
    this.placeCooldown = Math.max(0, this.placeCooldown - dt)
    this.bounceCooldown = Math.max(0, this.bounceCooldown - dt)
    this.stepCooldown = Math.max(0, this.stepCooldown - dt)
    if (this.jumpBuffer > 0) this.jumpBuffer -= dt

    // water at the feet?
    this.inWater = isWater(this.world.getBlock(this.pos.x, this.pos.y + 0.3, this.pos.z)) ||
      isWater(this.world.getBlock(this.pos.x, this.pos.y + 0.9, this.pos.z))

    const fwd = new THREE.Vector3(-Math.sin(this.cameraYaw), 0, -Math.cos(this.cameraYaw))
    const right = new THREE.Vector3(Math.cos(this.cameraYaw), 0, -Math.sin(this.cameraYaw))
    const wish = new THREE.Vector3()
    wish.addScaledVector(fwd, this.moveInput.y)
    wish.addScaledVector(right, this.moveInput.x)
    if (wish.lengthSq() > 1) wish.normalize()
    const moving = wish.lengthSq() > 0.001
    const wantsSprint = this.sprint && this.moveInput.y > 0.2
    let maxSpeed = wantsSprint ? 8.4 : 5.3
    if (this.inWater) maxSpeed *= 0.62
    if (this.emote === 'dance') maxSpeed = 0
    const accel = this.onGround ? 13 : 4.2
    const targetVelX = wish.x * maxSpeed
    const targetVelZ = wish.z * maxSpeed
    if (maxSpeed > 0) {
      this.vel.x = damp(this.vel.x, targetVelX, accel, dt)
      this.vel.z = damp(this.vel.z, targetVelZ, accel, dt)
    } else {
      this.vel.x = damp(this.vel.x, 0, 8, dt)
      this.vel.z = damp(this.vel.z, 0, 8, dt)
    }

    // gravity & swimming
    if (this.inWater) {
      this.vel.y -= 7 * dt
      this.vel.y = Math.max(this.vel.y, -2.4)
      if (this.jumpHeld) this.vel.y = Math.min(this.vel.y + 22 * dt, 3.6)
    } else {
      this.vel.y -= 26 * dt
      this.vel.y = Math.max(this.vel.y, -32)
    }

    if (this.onGround) this.coyote = 0.12
    else this.coyote = Math.max(0, this.coyote - dt)

    if (this.jumpBuffer > 0 && (this.coyote > 0 || this.inWater)) {
      if (this.inWater) {
        this.vel.y = 4.6
        this.game.sfx('splash', 0.5)
      } else {
        this.vel.y = 9.4
        this.game.sfx('jump', 0.7)
        this.game.particles.burst(this.pos.x, this.pos.y + 0.1, this.pos.z, 'grass', 5, 0.7)
      }
      this.jumpBuffer = 0
      this.coyote = 0
      this.onGround = false
      this.game.quests?.event('jump')
    }

    const wasGround = this.onGround
    this.moveWithCollision(dt)

    // landing
    if (!wasGround && this.onGround && this.vel.y <= 0.01) {
      this.game.sfx('land', 0.45)
      this.game.particles.burst(this.pos.x, this.pos.y + 0.05, this.pos.z, 'grass', 6, 0.5)
      // bounce pads
      const below = this.world.getKey(this.pos.x, this.pos.y - 0.2, this.pos.z)
      if (below === 'bounce' && this.bounceCooldown <= 0) {
        this.vel.y = 17.5
        this.onGround = false
        this.bounceCooldown = 0.35
        this.game.sfx('bounce', 0.8)
        this.game.particles.burst(this.pos.x, this.pos.y + 0.2, this.pos.z, 'bounce', 14, 1.4)
        this.game.quests?.event('bounce')
      }
    }

    if (this.pos.y < -12) this.resetToSpawn()

    // face movement direction
    const hspeed = Math.hypot(this.vel.x, this.vel.z)
    this.speed = hspeed
    if (hspeed > 0.4 && this.emote !== 'dance') {
      const targetFacing = Math.atan2(this.vel.x, this.vel.z)
      this.facing = dampAngle(this.facing, targetFacing, 14, dt)
    }
    if (this.emote === 'dance' && moving) {
      this.emote = ''
      this.emoteTimer = 0
    }

    this.updateTargeting(dt, time)
    this.updateVisual(dt, time)
    this.updateCamera(dt)

    // footsteps
    if (this.onGround && hspeed > 1.2) {
      this.walkTime += dt * hspeed
      if (this.walkTime > 1.55) {
        this.walkTime = 0
        this.game.sfx('step', 0.18)
      }
    }
  }

  moveWithCollision(dt) {
    const p = this.pos
    // X axis
    p.x += this.vel.x * dt
    if (this.collidesAt(p)) {
      if (this.tryStepUp()) { /* stepped */ } else { p.x -= this.vel.x * dt; this.vel.x = 0 }
    }
    // Z axis
    p.z += this.vel.z * dt
    if (this.collidesAt(p)) {
      if (this.tryStepUp()) { /* stepped */ } else { p.z -= this.vel.z * dt; this.vel.z = 0 }
    }
    // Y axis
    const oldY = p.y
    p.y += this.vel.y * dt
    if (this.collidesAt(p)) {
      p.y = oldY
      if (this.vel.y < 0) {
        this.onGround = true
      }
      this.vel.y = 0
    } else {
      this.onGround = false
    }
    // ground probe
    if (!this.onGround && this.vel.y <= 0) {
      const probe = { x: p.x, y: p.y - 0.04, z: p.z }
      if (this.collidesAt(probe)) this.onGround = true
    }
    if (this.onGround && this.vel.y < 0) this.vel.y = 0
  }

  tryStepUp() {
    if (!this.onGround || this.stepCooldown > 0) return false
    const oldY = this.pos.y
    this.pos.y += 1.02
    if (!this.collidesAt(this.pos)) {
      this.stepCooldown = 0.14
      return true
    }
    this.pos.y = oldY
    return false
  }

  updateTargeting(dt, time) {
    const dir = new THREE.Vector3()
    this.camera.getWorldDirection(dir)
    const hit = this.world.raycast(this.camera.position, dir, 9)
    const playerDist = hit ? Math.hypot(hit.x + .5 - this.pos.x, hit.y + .5 - (this.pos.y + 1), hit.z + .5 - this.pos.z) : Infinity
    if (hit && playerDist < 6.6) {
      this.target = hit
      this.highlight.visible = true
      this.highlightFace.visible = true
      this.highlight.position.set(hit.x + .5, hit.y + .5, hit.z + .5)
      this.highlightFace.position.copy(this.highlight.position)
      this.highlight.material.opacity = 0.7 + Math.sin(time * 4) * 0.25
      this.highlightFace.material.opacity = 0.06 + Math.sin(time * 4) * 0.03
      if (this.mineProgress > 0) {
        this.crack.visible = true
        this.crack.position.copy(this.highlight.position)
        this.crack.material.opacity = Math.min(1, this.mineProgress * 1.15)
      } else {
        this.crack.visible = false
      }
    } else {
      this.target = null
      this.highlight.visible = false
      this.highlightFace.visible = false
      this.crack.visible = false
      this.mineProgress = 0
    }

    // mining
    if (this.mineHold && this.target && this.mineCooldown <= 0) {
      if (!this.miningKey || this.miningKey !== `${this.target.x},${this.target.y},${this.target.z}`) {
        this.miningKey = `${this.target.x},${this.target.y},${this.target.z}`
        this.mineProgress = 0
      }
      const key = this.target.key
      const hardness = BLOCKS[key]?.hardness || 0.4
      this.mineProgress += dt / Math.max(0.12, hardness)
      // face the block while mining
      const tx = this.target.x + .5, tz = this.target.z + .5
      const targetFacing = Math.atan2(tx - this.pos.x, tz - this.pos.z)
      this.facing = dampAngle(this.facing, targetFacing, 18, dt)
      if (this.mineProgress >= 1) {
        this.breakTarget()
      }
    } else if (!this.mineHold) {
      this.mineProgress = 0
      this.miningKey = null
    }

    if (this.placeQueued) {
      this.placeQueued = false
      this.placeBlock()
    }

    this.game.ui?.setTargetInfo(this.target, this.mineProgress)
  }

  breakTarget() {
    const t = this.target
    if (!t) return
    const key = t.key
    if (!BLOCKS[key] || BLOCKS[key].liquid) { this.mineProgress = 0; return }
    const removed = this.world.removeBlock(t.x, t.y, t.z)
    if (!removed) { this.mineProgress = 0; return }
    this.mineProgress = 0
    this.miningKey = null
    this.mineCooldown = 0.06
    this.game.particles.burst(t.x + .5, t.y + .5, t.z + .5, key, 12, 1.1)
    this.game.sfx('break', 0.8)
    this.game.onBlockBroken(key, t)
  }

  placeBlock() {
    if (!this.target || this.placeCooldown > 0) return
    const key = this.selectedKey
    if (!key || !BLOCKS[key]?.placeable) return
    if ((this.game.inventory[key] || 0) <= 0) {
      this.game.notify(`Out of ${BLOCKS[key].name}!`, 'warn')
      this.game.sfx('deny', 0.6)
      return
    }
    const nx = this.target.x + this.target.normal[0]
    const ny = this.target.y + this.target.normal[1]
    const nz = this.target.z + this.target.normal[2]
    if (nx < 0 || nx >= WORLD || nz < 0 || nz >= WORLD || ny < 0 || ny >= HEIGHT) return
    const existing = this.world.getBlock(nx, ny, nz)
    if (existing !== 0 && !isWater(existing)) return
    // don't entomb yourself
    const b = {
      minX: nx, maxX: nx + 1, minY: ny, maxY: ny + 1, minZ: nz, maxZ: nz + 1
    }
    const p = this.getAABB()
    const overlap = b.minX < p.maxX - 0.02 && b.maxX > p.minX + 0.02 && b.minY < p.maxY - 0.02 && b.maxY > p.minY + 0.02 && b.minZ < p.maxZ - 0.02 && b.maxZ > p.minZ + 0.02
    if (overlap) {
      this.game.notify('Not enough room to build there.', 'warn')
      this.game.sfx('deny', 0.5)
      return
    }
    if (this.world.setBlock(nx, ny, nz, key)) {
      this.game.inventory[key]--
      this.placeCooldown = 0.14
      this.game.sfx('place', 0.7)
      this.game.particles.burst(nx + .5, ny + .5, nz + .5, key, 6, 0.5)
      this.game.onBlockPlaced(key, { x: nx, y: ny, z: nz })
      this.game.ui?.refreshInventory()
    }
  }

  updateVisual(dt, time) {
    this.character.root.position.copy(this.pos)
    this.character.root.rotation.y = this.facing
    this.character.update(dt, {
      speed: this.speed, grounded: this.onGround, time,
      mining: this.mineHold && !!this.target, emote: this.emote,
      lookPitch: -this.cameraPitch * 0.2
    })
  }

  updateCamera(dt) {
    const target = new THREE.Vector3(this.pos.x, this.pos.y + 1.42, this.pos.z)
    const offset = new THREE.Vector3(
      Math.sin(this.cameraYaw) * Math.cos(this.cameraPitch),
      Math.sin(this.cameraPitch),
      Math.cos(this.cameraYaw) * Math.cos(this.cameraPitch)
    ).multiplyScalar(this.cameraDist)
    let desired = target.clone().add(offset)
    // camera collision
    const dir = desired.clone().sub(target).normalize()
    const hit = this.world.raycast(target, dir, this.cameraDist + 0.4)
    if (hit) desired = target.clone().add(dir.multiplyScalar(Math.max(1.4, hit.distance - 0.35)))
    // keep camera inside the sky, not under the island
    if (desired.y < 0.6) desired.y = 0.6
    const k = 1 - Math.exp(-12 * dt)
    this.cameraPos.lerp(desired, k)
    this.cameraTarget.lerp(target, 1 - Math.exp(-18 * dt))
    this.camera.position.copy(this.cameraPos)
    this.camera.lookAt(this.cameraTarget)
    const targetFov = this.sprint && this.speed > 4 ? 68 : 62
    this.fov = damp(this.fov, targetFov, 6, dt)
    if (Math.abs(this.camera.fov - this.fov) > 0.05) {
      this.camera.fov = this.fov
      this.camera.updateProjectionMatrix()
    }
  }

  serialize() {
    return {
      x: this.pos.x, y: this.pos.y, z: this.pos.z,
      yaw: this.cameraYaw, pitch: this.cameraPitch, facing: this.facing,
      hat: this.character.hat
    }
  }
  load(data) {
    if (!data) return
    const x = Number(data.x), z = Number(data.z)
    if (Number.isFinite(x) && Number.isFinite(z) && x > 2 && x < WORLD - 2 && z > 2 && z < WORLD - 2) {
      this.pos.x = x; this.pos.z = z
      this.pos.y = Math.max(this.world.surfaceY(x, z) + 0.05, Math.min(HEIGHT - 3, Number(data.y) || 0))
      if (this.collidesAt(this.pos)) this.pos.y = this.world.surfaceY(x, z) + 0.05
    }
    if (Number.isFinite(data.yaw)) this.cameraYaw = data.yaw
    if (Number.isFinite(data.pitch)) this.cameraPitch = clamp(data.pitch, -0.38, 1.12)
    if (Number.isFinite(data.facing)) this.facing = data.facing
    this.cameraTarget.set(this.pos.x, this.pos.y + 1.42, this.pos.z)
    this.cameraPos.copy(this.cameraTarget)
  }
}

import * as THREE from '../vendor/three.module.js'
import { blockColor } from './blocks.js'

export class Particles {
  constructor(scene) {
    this.scene = scene
    this.geo = new THREE.BoxGeometry(0.14, 0.14, 0.14)
    this.pool = []
    this.active = []
    for (let i = 0; i < 180; i++) {
      const m = new THREE.Mesh(this.geo, new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 1 }))
      m.visible = false
      m.matrixAutoUpdate = true
      this.scene.add(m)
      this.pool.push(m)
    }
  }

  _get() {
    const m = this.pool.pop()
    if (!m) {
      const old = this.active.shift()
      return old || null
    }
    return m
  }

  burst(x, y, z, key, count = 10, power = 1) {
    const color = new THREE.Color(blockColor(key))
    for (let i = 0; i < count; i++) {
      const m = this._get()
      if (!m) return
      m.visible = true
      m.material.color.copy(color).offsetHSL((Math.random() - .5) * .06, 0, (Math.random() - .5) * .12)
      m.material.opacity = 1
      m.position.set(x + (Math.random() - .5) * .6, y + (Math.random() - .5) * .6, z + (Math.random() - .5) * .6)
      const s = 0.5 + Math.random() * 1.1
      m.scale.setScalar(s)
      m.rotation.set(Math.random() * 3, Math.random() * 3, Math.random() * 3)
      this.active.push({
        mesh: m, life: 0.45 + Math.random() * 0.5, maxLife: 0.95,
        vx: (Math.random() - .5) * 4 * power,
        vy: (Math.random() * 3.2 + 1) * power,
        vz: (Math.random() - .5) * 4 * power,
        spin: (Math.random() - .5) * 10,
        gravity: 12
      })
    }
  }

  sparkle(x, y, z, color = '#ffe28a', count = 14, power = 1) {
    const c = new THREE.Color(color)
    for (let i = 0; i < count; i++) {
      const m = this._get()
      if (!m) return
      m.visible = true
      m.material.color.copy(c)
      m.material.opacity = 1
      m.position.set(x, y, z)
      m.scale.setScalar(0.4 + Math.random() * 0.8)
      m.rotation.set(Math.random() * 3, Math.random() * 3, Math.random() * 3)
      const a = Math.random() * Math.PI * 2
      const sp = (0.8 + Math.random() * 2.2) * power
      this.active.push({
        mesh: m, life: 0.7 + Math.random() * 0.9, maxLife: 1.6,
        vx: Math.cos(a) * sp, vy: 0.6 + Math.random() * 2.4 * power, vz: Math.sin(a) * sp,
        spin: (Math.random() - .5) * 8, gravity: 2.5
      })
    }
  }

  confetti(x, y, z, count = 40) {
    const colors = ['#ffd45e', '#ff6fa8', '#6fd6f2', '#8c5ad6', '#7ac653', '#fff3c0']
    for (let i = 0; i < count; i++) {
      const m = this._get()
      if (!m) return
      m.visible = true
      m.material.color.set(colors[i % colors.length])
      m.material.opacity = 1
      m.position.set(x + (Math.random() - .5) * 2, y + Math.random() * .5, z + (Math.random() - .5) * 2)
      m.scale.setScalar(0.5 + Math.random())
      m.rotation.set(Math.random() * 3, Math.random() * 3, Math.random() * 3)
      this.active.push({
        mesh: m, life: 1.4 + Math.random() * 1.4, maxLife: 2.8,
        vx: (Math.random() - .5) * 6, vy: 3 + Math.random() * 5, vz: (Math.random() - .5) * 6,
        spin: (Math.random() - .5) * 12, gravity: 6
      })
    }
  }

  update(dt) {
    for (let i = this.active.length - 1; i >= 0; i--) {
      const p = this.active[i]
      p.life -= dt
      if (p.life <= 0) {
        p.mesh.visible = false
        this.pool.push(p.mesh)
        this.active.splice(i, 1)
        continue
      }
      p.vy -= p.gravity * dt
      p.mesh.position.x += p.vx * dt
      p.mesh.position.y += p.vy * dt
      p.mesh.position.z += p.vz * dt
      p.mesh.rotation.x += p.spin * dt
      p.mesh.rotation.y += p.spin * 0.7 * dt
      p.mesh.material.opacity = Math.min(1, p.life * 2.2)
      const s = Math.min(1, p.life * 2) * (p.mesh.scale.x > 0 ? 1 : 1)
      p.mesh.scale.multiplyScalar(1 - dt * 0.8)
    }
  }
}

export class Audio {
  constructor() {
    this.ctx = null
    this.master = null
    this.musicGain = null
    this.ambientGain = null
    this.muted = false
    this.started = false
    this.night = false
    this._musicTimer = null
    this._birdTimer = null
    this._step = 0
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume()
      return
    }
    const Ctx = window.AudioContext || window.webkitAudioContext
    if (!Ctx) return
    this.ctx = new Ctx()
    this.master = this.ctx.createGain()
    this.master.gain.value = this.muted ? 0 : 0.62
    this.master.connect(this.ctx.destination)
    this.musicGain = this.ctx.createGain()
    this.musicGain.gain.value = 0.14
    this.musicGain.connect(this.master)
    this.ambientGain = this.ctx.createGain()
    this.ambientGain.gain.value = 0.35
    this.ambientGain.connect(this.master)
    this.noise = this.makeNoise()
    this.startAmbient()
    this.startMusic()
    this.started = true
  }

  makeNoise() {
    const len = this.ctx.sampleRate * 2
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate)
    const d = buf.getChannelData(0)
    let last = 0
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1
      last = (last + 0.02 * white) / 1.02
      d[i] = last * 3.2
    }
    return buf
  }

  startAmbient() {
    const src = this.ctx.createBufferSource()
    src.buffer = this.noise
    src.loop = true
    const filter = this.ctx.createBiquadFilter()
    filter.type = 'lowpass'
    filter.frequency.value = 520
    const gain = this.ctx.createGain()
    gain.gain.value = 0.055
    src.connect(filter).connect(gain).connect(this.ambientGain)
    src.start()
    this.windGain = gain

    const scheduleBird = () => {
      if (!this.ctx) return
      const delay = (4 + Math.random() * 7) * 1000
      this._birdTimer = setTimeout(() => {
        if (this.started && !this.night) this.chirp()
        scheduleBird()
      }, delay)
    }
    scheduleBird()
  }

  chirp() {
    if (!this.ctx) return
    const t = this.ctx.currentTime
    const notes = 2 + Math.floor(Math.random() * 3)
    for (let i = 0; i < notes; i++) {
      const o = this.ctx.createOscillator()
      const g = this.ctx.createGain()
      o.type = 'sine'
      const base = 1700 + Math.random() * 1400
      o.frequency.setValueAtTime(base, t + i * 0.11)
      o.frequency.exponentialRampToValueAtTime(base * (1.2 + Math.random() * .4), t + i * 0.11 + 0.06)
      g.gain.setValueAtTime(0, t + i * 0.11)
      g.gain.linearRampToValueAtTime(0.05, t + i * 0.11 + 0.015)
      g.gain.exponentialRampToValueAtTime(0.0001, t + i * 0.11 + 0.1)
      o.connect(g).connect(this.ambientGain)
      o.start(t + i * 0.11); o.stop(t + i * 0.11 + 0.12)
    }
  }

  startMusic() {
    if (!this.ctx) return
    const scale = [0, 2, 4, 7, 9, 12, 14, 16]
    const base = 196
    const play = () => {
      if (!this.ctx || !this.started) return
      const t = this.ctx.currentTime
      if (!this.night) {
        const idx = Math.floor(Math.random() * scale.length)
        const f = base * Math.pow(2, scale[idx] / 12)
        this.pluck(f, t, 0.16)
        if (Math.random() > 0.55) this.pluck(f * 1.5, t + 0.22, 0.09)
        if (this._step % 4 === 0) this.pad(base / 2, t, 0.5)
      } else {
        const idx = Math.floor(Math.random() * 5)
        const f = base * Math.pow(2, [0, 3, 7, 10, 12][idx] / 12)
        this.pluck(f, t, 0.11)
        if (this._step % 3 === 0) this.pad(base / 2, t, 0.4)
      }
      this._step++
      this._musicTimer = setTimeout(play, 1800 + Math.random() * 1400)
    }
    play()
  }

  pluck(freq, t, vol) {
    const o = this.ctx.createOscillator()
    const g = this.ctx.createGain()
    const f = this.ctx.createBiquadFilter()
    o.type = 'triangle'
    f.type = 'lowpass'
    f.frequency.value = 1800
    o.frequency.setValueAtTime(freq, t)
    g.gain.setValueAtTime(0, t)
    g.gain.linearRampToValueAtTime(vol, t + 0.02)
    g.gain.exponentialRampToValueAtTime(0.0001, t + 1.1)
    o.connect(f).connect(g).connect(this.musicGain)
    o.start(t); o.stop(t + 1.2)
  }

  pad(freq, t, vol) {
    const o = this.ctx.createOscillator()
    const g = this.ctx.createGain()
    o.type = 'sine'
    o.frequency.value = freq
    g.gain.setValueAtTime(0, t)
    g.gain.linearRampToValueAtTime(vol * 0.1, t + 1.2)
    g.gain.linearRampToValueAtTime(0.0001, t + 4.5)
    o.connect(g).connect(this.musicGain)
    o.start(t); o.stop(t + 4.6)
  }

  tone(freq, dur, type = 'sine', vol = 0.15, slide = null, delay = 0) {
    if (!this.ctx || this.muted) return
    const t = this.ctx.currentTime + delay
    const o = this.ctx.createOscillator()
    const g = this.ctx.createGain()
    o.type = type
    o.frequency.setValueAtTime(freq, t)
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(30, slide), t + dur)
    g.gain.setValueAtTime(0, t)
    g.gain.linearRampToValueAtTime(vol, t + 0.012)
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    o.connect(g).connect(this.master)
    o.start(t); o.stop(t + dur + 0.02)
  }

  noiseBurst(dur = 0.12, freq = 1000, vol = 0.15, type = 'bandpass') {
    if (!this.ctx || this.muted) return
    const t = this.ctx.currentTime
    const src = this.ctx.createBufferSource()
    src.buffer = this.noise
    const f = this.ctx.createBiquadFilter()
    f.type = type
    f.frequency.value = freq
    f.Q.value = 0.8
    const g = this.ctx.createGain()
    g.gain.setValueAtTime(vol, t)
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    src.connect(f).connect(g).connect(this.master)
    src.start(t); src.stop(t + dur + 0.02)
  }

  sfx(name, volume = 1) {
    if (!this.ctx) return
    const v = Math.min(1, volume)
    switch (name) {
      case 'step': this.noiseBurst(0.06, 420, 0.045 * v, 'lowpass'); break
      case 'jump': this.tone(260, 0.16, 'sine', 0.1 * v, 460); break
      case 'land': this.noiseBurst(0.1, 260, 0.1 * v, 'lowpass'); this.tone(120, 0.09, 'sine', 0.06 * v, 70); break
      case 'break': this.noiseBurst(0.14, 900, 0.2 * v, 'bandpass'); this.tone(180, 0.1, 'square', 0.035 * v, 90); break
      case 'place': this.noiseBurst(0.07, 600, 0.12 * v, 'lowpass'); this.tone(150, 0.08, 'triangle', 0.1 * v, 110); break
      case 'bounce': this.tone(280, 0.28, 'sine', 0.16 * v, 900); this.tone(560, 0.2, 'triangle', 0.05 * v, 1200, 0.04); break
      case 'splash': this.noiseBurst(0.28, 1800, 0.14 * v, 'highpass'); break
      case 'coin': this.tone(1046, 0.09, 'triangle', 0.1 * v); this.tone(1568, 0.14, 'triangle', 0.09 * v, null, 0.07); break
      case 'quest': [523, 659, 784, 1046].forEach((f, i) => this.tone(f, 0.22, 'triangle', 0.09 * v, null, i * 0.1)); break
      case 'level': [523, 659, 784, 1046, 1318].forEach((f, i) => this.tone(f, 0.4, 'sine', 0.1 * v, null, i * 0.09)); break
      case 'ui': this.tone(620, 0.045, 'sine', 0.05 * v); break
      case 'deny': this.tone(140, 0.12, 'square', 0.06 * v, 110); break
      case 'emote': this.tone(700, 0.08, 'sine', 0.06 * v, 1000); break
      case 'beacon': [784, 988, 1175, 1568].forEach((f, i) => this.tone(f, 0.7, 'sine', 0.07 * v, null, i * 0.14)); break
      case 'sell': this.tone(880, 0.08, 'square', 0.05 * v); this.tone(660, 0.12, 'square', 0.04 * v, null, 0.06); break
      default: break
    }
  }

  setMuted(m) {
    this.muted = m
    if (this.master) this.master.gain.setTargetAtTime(m ? 0 : 0.62, this.ctx.currentTime, 0.05)
  }

  setNight(n) {
    this.night = n
    if (this.windGain) this.windGain.gain.setTargetAtTime(n ? 0.09 : 0.05, this.ctx.currentTime, 1.5)
  }
}

