}
.mini-wrap {
  width: 172px; height: 172px;
  border-radius: 50%;
  padding: 5px;
  position: relative;
  background: radial-gradient(circle at 40% 30%, rgba(64, 56, 110, 0.95), rgba(20, 18, 40, 0.96));
  box-shadow: var(--shadow), inset 0 0 0 2px rgba(255, 212, 94, 0.12);
}
#minimap {
  width: 100%; height: 100%;
  border-radius: 50%;
  display: block;
  background: #223;
}
.compass-n {
  position: absolute;
  top: 3px; left: 50%; transform: translateX(-50%);
  font-family: var(--font-display);
  font-size: 11px; font-weight: 800;
  color: var(--gold);
  text-shadow: 0 1px 4px #000;
  background: rgba(20, 18, 40, 0.7);
  border-radius: 999px;
  padding: 1px 6px;
}
.icon-row { display: flex; gap: 7px; }
.icon-btn {
  width: 38px; height: 38px;
  border-radius: 13px;
  border: 1px solid var(--panel-line);
  background: linear-gradient(160deg, rgba(46, 40, 84, 0.9), rgba(24, 21, 45, 0.94));
  color: var(--cream);
  font-family: var(--font-display);
  font-size: 18px; font-weight: 800;
  display: grid; place-items: center;
  cursor: pointer;
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.25);
  transition: transform 0.12s ease, background 0.2s ease;
  backdrop-filter: blur(10px);
}
.icon-btn:hover { transform: translateY(-2px); background: rgba(64, 56, 110, 0.95); }
.icon-btn:active { transform: translateY(1px); }
#btn-sound.muted { color: var(--muted); opacity: 0.55; }

#crosshair {
  position: absolute;
  left: 50%; top: 50%;
  transform: translate(-50%, -50%);
  width: 28px; height: 28px;
  display: grid; place-items: center;
  opacity: 0.85;
  transition: opacity 0.2s ease;
}
.ch-dot {
  width: 4px; height: 4px; border-radius: 50%;
  background: var(--cream);
  box-shadow: 0 0 0 1px rgba(20, 16, 36, 0.6), 0 0 6px rgba(255, 255, 255, 0.4);
}
.ch-ring {
  position: absolute; inset: 0;
  border: 1px solid rgba(255, 246, 226, 0.28);
  border-radius: 50%;
}
.target-label {
  position: absolute;
  left: 50%; top: calc(50% + 30px);
  transform: translateX(-50%);
  font-size: 11px; font-weight: 800;
