.hotbar-hint { font-size: 10px; font-weight: 700; color: rgba(255, 246, 226, 0.55); text-shadow: 0 1px 3px rgba(0, 0, 0, 0.7); }
.hotbar-hint span { color: var(--gold-soft); }
.hotbar-hint .dot { opacity: 0.5; margin: 0 3px; }

.toast-stack {
  position: absolute;
  top: 96px;
  left: 50%;
  transform: translateX(-50%);
