input.newString:
@media (max-width: 900px) and (max-height: 500px) {
  .start-screen { align-items: flex-start; padding-top: 18px; overflow: auto; }
  .start-inner { gap: 10px; }
  .logo span { font-size: 42px; }
  .tagline { display: none; }
  .feature-chips { display: none; }

  /* Landscape phones: keep the objective at the top, free the play field,
     and shrink the controls so they never sit on top of the hotbar. */
  .quest-tracker { display: none; }
  .top-center {
    display: flex;
    top: max(8px, env(safe-area-inset-top));
    left: 50%;
    transform: translateX(-50%);
    width: auto;
    max-width: 46vw;
    align-items: center;
    text-align: center;
    gap: 0;
  }
  .realm-banner { display: none; }
  .objective { max-width: 46vw; font-size: 10px; padding: 5px 10px; line-height: 1.3; }
  .toast-stack { top: 48px; width: min(360px, 54vw); }
  .hud-top-left { width: 228px; }
  .player-card { padding: 6px 8px; gap: 8px; }
  .avatar-ring { width: 38px; height: 38px; }
  .player-name { font-size: 14px; }
  .xp-text { font-size: 8px; }
  .mini-wrap { width: 84px; height: 84px; }
  .icon-row { display: none; }
  .joystick { width: 96px; height: 96px; bottom: max(64px, calc(env(safe-area-inset-bottom) + 58px)); }
  .joystick-ring { inset: 18px; }
  .stick { width: 44px; height: 44px; margin: -22px 0 0 -22px; }
  .action-cluster { bottom: max(58px, calc(env(safe-area-inset-bottom) + 52px)); transform: scale(0.88); transform-origin: bottom right; }
  body.touch .hotbar { gap: 2px; padding: 3px; }
  body.touch .slot { width: 38px; height: 38px; border-radius: 8px; }
  body.touch .slot img { width: 24px; height: 24px; }
  body.touch .slot-count { font-size: 7px; }
  body.touch .slot.selected { transform: translateY(-3px); }
}

